import { useState } from "react";
import { useLocation } from "react-router-dom";

import logo from "../navbar/logo.png";
import "./login.css";

export default function Login() {
  const location = useLocation();
  const [signup, setSignup] = useState(
    location.state?.mode === "signup" ? true : false,
  );
  const [loginData, setLoginData] = useState({
    email: "",
    password: "",
  });

  const [signupData, setSignupData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    password: "",
  });
  const toggle = () => {
    setSignup((prev) => !prev);
  };
  const handleLoginSubmit = async (e) => {
    try {
      e.preventDefault();

      const res1 = await fetch(
        "https://vercel-backend-whitepace.vercel.app/api/login",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify(loginData),
        },
      );
      const ldata = await res1.json();

      console.log(ldata);

      if (res1.ok) {
        alert("Login successful!");

        localStorage.setItem("username", ldata.username);

        window.location.href = "/dashboard";
      } else {
        alert(ldata.msg || "Login failed");
      }
    } catch (err) {
      alert("ERROR: " + err.message + " server error");
    }
  };
  const handleSignupSubmit = async (e) => {
    try {
      e.preventDefault();
      const res = await fetch(
        "https://vercel-backend-whitepace.vercel.app/api/signup",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify(signupData),
        },
      );

      const sdata = await res.json();

      console.log(sdata);

      if (res.ok) {
        alert("Signup successful!");
        setSignup(false); // switch to login
      } else {
        alert(sdata.msg);
      }
    } catch (err) {
      alert("ERROR: " + err.message + " server error");
    }
  };

  return (
    <div className="login-container">
      <div className="login" style={{ display: signup ? "none" : "block" }}>
        <h2>Login</h2>
        <form onSubmit={handleLoginSubmit}>
          <label className="labels">Email</label>
          <br />
          <input
            type="email"
            name="email"
            className="inputs"
            required
            value={loginData.email}
            onChange={(e) =>
              setLoginData({ ...loginData, email: e.target.value })
            }
          />
          <br />
          <label className="labels">Password</label>
          <br />
          <input
            type="password"
            name="password"
            className="inputs"
            required
            value={loginData.password}
            onChange={(e) =>
              setLoginData({ ...loginData, password: e.target.value })
            }
          />
          <br />
          <input type="submit" value="Login" className="submit-btn" />
        </form>
        <p id="p">
          Don't have an account?
          <a
            href="#"
            onClick={() => {
              setSignup(true);
            }}
          >
            Signup
          </a>
        </p>
      </div>
      <div className="signup" style={{ display: signup ? "block" : "none" }}>
        <h2>Signup</h2>
        <form onSubmit={handleSignupSubmit}>
          <label className="labels">First Name</label>
          <br />
          <input
            type="text"
            name="firstName"
            className="inputs"
            required
            value={signupData.firstName}
            onChange={(e) =>
              setSignupData({ ...signupData, firstName: e.target.value })
            }
          />
          <br />
          <label className="labels">Last Name</label>
          <br />
          <input
            type="text"
            name="lastName"
            className="inputs"
            required
            value={signupData.lastName}
            onChange={(e) =>
              setSignupData({ ...signupData, lastName: e.target.value })
            }
          />
          <br />
          <label className="labels">Email</label>
          <br />
          <input
            type="email"
            name="email"
            className="inputs"
            required
            value={signupData.email}
            onChange={(e) =>
              setSignupData({ ...signupData, email: e.target.value })
            }
          />
          <br />
          <label className="labels">Password</label>
          <br />
          <input
            type="password"
            name="password"
            className="inputs"
            required
            value={signupData.password}
            onChange={(e) =>
              setSignupData({ ...signupData, password: e.target.value })
            }
          />
          <br />
          <input type="submit" value="Signup" className="submit-btn" />
        </form>
        <p id="p">
          Already have an account?
          <a
            href="#"
            onClick={() => {
              setSignup(false);
            }}
          >
            Login
          </a>
        </p>
      </div>
      <img className="bg-logo" src={logo} alt="" />
    </div>
  );
}
