import "./sponser.css";
import element from "../../global/Element.png";
import google from "../../global/google.png";
import slack from "../../global/slack.png";
import apple from "../../global/apple.png";
import microsoft from "../../global/microsoft.png";

export default function Sponser() {
  return (
    <section id="Sponser">
      <h1>
        Our Sponsers <img className="sponser-element" src={element} />
      </h1>
      <div className="sponser-container">
        <img src={apple} />
        <div>
          <img src={microsoft} />
          <h2>Microsoft</h2>
        </div>
        <div>
          <img src={slack} />
          <h2>slack</h2>
        </div>
        <img className="google" src={google} />
      </div>
    </section>
  );
}
