import "./work.css";
import { FiArrowRight } from "react-icons/fi";
import element from "../../global/Element.png";
import { easeOut, motion, scale } from "framer-motion";

export default function Work() {
  return (
    <section id="Work">
      <div className="project-container">
        <div className="project-content">
          <motion.h1
            initial={{ opacity: 0, x: 100 }}
            whileInView={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.8 }}
          >
            Project Management
            <img
              className="element project-element"
              src={element}
              alt="element"
            />
          </motion.h1>
          <motion.p
            initial={{ opacity: 0, x: -100 }}
            whileInView={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.8 }}
          >
            Images, videos, PDFs and audio files are supported. Create math
            expressions and diagrams directly from the app. Take photos with the
            mobile app and save them to a note.
          </motion.p>
          <a href="#">
            <motion.button
              initial={{ opacity: 0, x: 100 }}
              whileInView={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.8 }}
              className="buttons"
            >
              Get Started <FiArrowRight id="arrowright" />
            </motion.button>
          </a>
        </div>
        <motion.div
          initial={{ opacity: 0, rotateX: 90 }}
          whileInView={{ opacity: 1, rotateX: 0 }}
          transition={{ duration: 0.8 }}
          className="project-image image-container"
        ></motion.div>
      </div>
      <div className="work-container">
        <motion.div
          initial={{ opacity: 0, rotate: 180 }}
          whileInView={{ opacity: 1, rotate: 0 }}
          transition={{ duration: 0.8 }}
          className="work-image"
        ></motion.div>
        <div className="work-content">
          <motion.h1
            initial={{ opacity: 0, x: 100 }}
            whileInView={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.8 }}
          >
            Work together
            <img className="element work-element" src={element} alt="element" />
          </motion.h1>
          <motion.p
            initial={{ opacity: 0, x: -100 }}
            whileInView={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.8 }}
          >
            With whitepace, share your notes with your colleagues and
            collaborate on them. You can also publish a note to the internet and
            share the URL with others.
          </motion.p>
          <a href="#">
            <motion.button
              initial={{ opacity: 0, scaleX: 0 }}
              whileInView={{ opacity: 1, scaleX: 1 }}
              transition={{ duration: 0.5 }}
              style={{ transformOrigin: "left", ease: "easeOut" }}
              className="buttons"
            >
              Try it now <FiArrowRight id="arrowright" />
            </motion.button>
          </a>
        </div>
      </div>
    </section>
  );
}
