import "./plan.css";
import element from "../../global/Element.png";
import { Swiper, SwiperSlide } from "swiper/react";
import { Pagination, Scrollbar, A11y } from "swiper/modules";
import { LuCircleCheckBig } from "react-icons/lu";

import "swiper/css";
import "swiper/css/pagination";
import "swiper/css/scrollbar";

export default function Plan() {
  return (
    <setion id="Plan">
      <div className="plan-content">
        <h1>
          Choose Your Plan <img className="plan-element" src={element} />
        </h1>
        <p>
          Whether you want to get organized, keep your personal life on track,
          or boost workplace productivity, Evernote has the right plan for you.
        </p>
      </div>
      <div className="plan-slider">
        <Swiper
          modules={[Pagination, A11y]}
          spaceBetween={32}
          slidesPerView={3}
          pagination={{ clickable: true }}
          scrollbar={{ draggable: true }}
          breakpoints={{
            0: { slidesPerView: 1 },
            768: { slidesPerView: 2 },
            1024: { slidesPerView: 3 },
          }}
        >
          {/* FREE PLAN */}
          <SwiperSlide>
            <div className="plan-card free">
              <h5>Free</h5>
              <h2>$0</h2>
              <p>Capture ideas and find them quickly</p>

              <ul className="feature-list">
                <li>
                  <LuCircleCheckBig /> Sync unlimited devices
                </li>
                <li>
                  <LuCircleCheckBig /> 10 GB monthly uploads
                </li>
                <li>
                  <LuCircleCheckBig /> 200 MB max. note size
                </li>
                <li>
                  <LuCircleCheckBig /> Customize Home dashboard and access extra
                  widgets
                </li>
                <li>
                  <LuCircleCheckBig /> Connect primary Google Calendar account
                </li>
                <li>
                  <LuCircleCheckBig /> Add due dates, reminders, and
                  notifications to your tasks
                </li>
              </ul>

              <a href="#">
                <button className="btn-free">Get Started</button>
              </a>
            </div>
          </SwiperSlide>

          {/* PERSONAL PLAN – BLUE CENTER CARD */}
          <SwiperSlide>
            <div className="plan-card personal">
              <h5>Personal</h5>
              <h2>$11.99</h2>
              <p>Keep home and family on track</p>

              <ul className="feature-list">
                <li>
                  <LuCircleCheckBig /> Sync unlimited devices
                </li>
                <li>
                  <LuCircleCheckBig /> 10 GB monthly uploads
                </li>
                <li>
                  <LuCircleCheckBig /> 200 MB max. note size
                </li>
                <li>
                  <LuCircleCheckBig /> Customize Home dashboard and access extra
                  widgets
                </li>
                <li>
                  <LuCircleCheckBig /> Connect primary Google Calendar account
                </li>
                <li>
                  <LuCircleCheckBig /> Add due dates, reminders, and
                  notifications to your tasks
                </li>
              </ul>

              <a href="#">
                <button className="btn-personal">Get Started</button>
              </a>
            </div>
          </SwiperSlide>

          {/* ORGANIZATION PLAN */}
          <SwiperSlide>
            <div className="plan-card organization">
              <h5>Organization</h5>
              <h2>$49.99</h2>
              <p>Capture ideas and find them quickly</p>

              <ul className="feature-list">
                <li>
                  <LuCircleCheckBig /> Sync unlimited devices
                </li>
                <li>
                  <LuCircleCheckBig /> 10 GB monthly uploads
                </li>
                <li>
                  <LuCircleCheckBig /> 200 MB max. note size
                </li>
                <li>
                  <LuCircleCheckBig /> Customize Home dashboard and access extra
                  widgets
                </li>
                <li>
                  <LuCircleCheckBig /> Connect primary Google Calendar account
                </li>
                <li>
                  <LuCircleCheckBig /> Add due dates, reminders, and
                  notifications to your tasks
                </li>
              </ul>

              <a href="#">
                <button className="btn-org">Get Started</button>
              </a>
            </div>
          </SwiperSlide>
        </Swiper>
      </div>
    </setion>
  );
}
