import "./extension.css";
import { FiArrowRight } from "react-icons/fi";
import element from "../../global/Element.png";
import { easeOut, motion } from "framer-motion";
export default function Extension() {
  return (
    <section id="Extension">
      <div className="extension-content">
        <motion.h1
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          transition={{ duration: 0.8 }}
        >
          Use as Extension
          <img className="ext-element" src={element} alt="element" />
        </motion.h1>
        <motion.p
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          transition={{ duration: 0.8 }}
        >
          Use the web clipper extension, available on Chrome and Firefox, to
          save web pages or take screenshots as notes.
        </motion.p>
        <a
          href="https://chromewebstore.google.com/detail/web-clipper/mhfbofiokmppgdliakminbgdgcmbhbac"
          target="blank"
        >
          <motion.button
            initial={{ opacity: 0 }}
            whileInView={{ opacity: 1 }}
            transition={{ duration: 0.8 }}
            className="buttons"
          >
            Get Started <FiArrowRight id="arrowright" />
          </motion.button>
        </a>
      </div>
      <motion.div
        initial={{ opacity: 0 }}
        whileInView={{ opacity: 1 }}
        transition={{ duration: 1 }}
        className="extension-frame"
      ></motion.div>
    </section>
  );
}
